# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::MetricsClient do
  it "metrics client sends no request without a service token and never echoes the token after a 401" do
    base_url = "http://timekeeping.test"
    metrics_url = "#{base_url}/internal/v1/metrics"
    stub_request(:get, metrics_url).to_return(status: 401, body: JSON.generate({ "reason" => "unauthorized" }))

    # "read with the service identity": an empty token must never become an
    # unauthenticated request that reads as a healthy, empty metrics body.
    allow(ENV).to receive(:[]).and_call_original
    allow(ENV).to receive(:[]).with("TIMEKEEPING_BASE_URL").and_return(base_url)
    allow(ENV).to receive(:[]).with("TIMEKEEPING_SERVICE_TOKEN").and_return("")
    expect { described_class.new.fetch }.to raise_error(Timekeeping::MetricsClient::Error)
    expect(a_request(:get, metrics_url)).not_to have_been_made

    token = "service-#{SecureRandom.hex(24)}"
    allow(ENV).to receive(:[]).with("TIMEKEEPING_SERVICE_TOKEN").and_return(token)
    expect { described_class.new.fetch }.to raise_error(Timekeeping::MetricsClient::Error) { |error|
      expect(error.message).not_to include(token)
    }
    expect(a_request(:get, metrics_url).with(headers: { "Authorization" => "Bearer #{token}" })).to have_been_made.once
  end
end
